//! The extension's build script: the gem's version, and nothing else. The
//! Lexbor layout the reference reads is generated by `reference/build.rs`;
//! nothing built here reads Lexbor.
// The crate's panic gate does not apply here: a build script reports failure BY
// panicking - cargo prints the message and stops the build - so aborting is the
// interface, not a missing error path. Nothing in this file ships.
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

fn main() {
    println!("cargo:rerun-if-changed=build.rs");
    gem_version();
}

/// Embed the gem's version (`lib/makiri/version.rb`, the one place it is
/// written) as `MAKIRI_GEM_VERSION`, which `init` publishes as
/// `Makiri::NATIVE_VERSION` for `lib/makiri.rb` to check the loaded binary
/// against. Read from the source rather than passed in by extconf, so every
/// cargo build of the extension carries it and none can carry a stale one.
fn gem_version() {
    let manifest = std::path::PathBuf::from(std::env::var("CARGO_MANIFEST_DIR").unwrap());
    let path = manifest.join("../../../lib/makiri/version.rb");
    println!("cargo:rerun-if-changed={}", path.display());
    let source = std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("cannot read {}: {e}", path.display()));
    /* `VERSION = "x"` or `VERSION = 'x'`, a trailing `.freeze` or comment
     * allowed: the literal is what is between the first quote and its match. */
    let version = source
        .lines()
        .find_map(|line| {
            let rest = line.trim().strip_prefix("VERSION")?.trim_start();
            let rest = rest.strip_prefix('=')?.trim_start();
            let quote = rest.chars().next().filter(|c| *c == '"' || *c == '\'')?;
            let body = &rest[1..];
            body.find(quote).map(|end| &body[..end])
        })
        .filter(|v| !v.is_empty())
        .unwrap_or_else(|| {
            panic!(
                "build.rs reads the gem version from a `VERSION = \"x.y.z\"` line in {}, \
                 and found none",
                path.display()
            )
        });
    println!("cargo:rustc-env=MAKIRI_GEM_VERSION={version}");
}
